document.addEventListener('click',e=>{const el=e.target.closest('button,a[data-language]');if(!el)return;if(busy){e.preventDefault();toast(t('正在檢索與生成，請稍候。','Searching and generating. Please wait.'));return;}if(el.matches('[data-language]')){e.preventDefault();switchLanguage();return;}if(el.dataset.nav){if($('#class-form'))capture();if(view==='plan')syncPlan();navigate(el.dataset.nav);return;}if(el.dataset.fill!==undefined){const i=Number(el.dataset.fill);$('#problem').value=exampleProblems[i];$('#strategy').value=strategies[i].id;$('#problem').focus();return;}if(el.dataset.guideExample){const junior=el.dataset.guideExample==='junior';draft={...blank(),level:el.dataset.guideExample,subject:subjects[lang][junior?3:0],students:junior?32:30,minutes:junior?15:12,topic:junior?t('比較兩個科學解釋','Comparing two scientific explanations'):t('故事人物的選擇','A character’s choices'),strategy:junior?'reason':'think',goal:junior?t('比較兩個解釋，指出各自依據及未知之處。','Compare two explanations, identify their evidence and note uncertainty.'):t('每人先提出想法，再用一個理由解釋人物的選擇。','Each pupil prepares an idea and a reason for a character’s choice.')};activeId=null;plan=null;navigate('create');return;}if(el.dataset.source){showSource(el.dataset.source);return;}if(el.dataset.ai){generate(el.dataset.ai);return;}if(el.dataset.sample){draft.strategy=el.dataset.sample;plan=samplePlan(draft,lang);activeId=null;navigate('plan');return;}if(el.dataset.open){open(el.dataset.open);return;}if(el.dataset.review){open(el.dataset.review,'reflect');return;}if(el.dataset.delete){if(confirm(t('刪除此活動及回顧？無法復原，建議先下載備份。','Delete this activity and reflection? This cannot be undone; download a backup first.'))){const prev=records;records=records.filter(r=>r.id!==el.dataset.delete);if(persist())navigate('history');else records=prev;}return;}switch(el.dataset.action){case'new':draft=blank();plan=null;activeId=null;navigate('home');break;case'sample-start':{const form=$('#class-form');if(!form.reportValidity())return;capture();if(!draft.goal)draft.goal=t('每位學生能參與活動，並用理由解釋自己的想法。','Each pupil participates and explains an idea with a reason.');plan=samplePlan(draft,lang);activeId=null;navigate('plan');break;}case'copy':copyActivity();break;case'save':save();break;case'reflect':if(save(true))navigate('reflect');break;case'reflect-ai':reflectAI();break;case'export':exportRecords();break;case'print':syncPlan();document.querySelectorAll('[data-step],[data-extra]').forEach(x=>x.nextElementSibling.textContent=x.value);document.querySelectorAll('.evidence-details').forEach(detail=>detail.open=true);$('#teacher-note').nextElementSibling.textContent=plan.teacherNote;window.print();break;case'refresh-status':checkStatus();break;}});
